int nearest_rail_point(Vec4 *from, s32 **outOwner, Vec4 *to, s32 *outI, f32 *outF, s32 *outKind,
                      s32 *skip, s32 *only)
{
    Vec4 pos;
    s32 gotI;
    f32 gotF;
    s32 i;
    Vec4 *p = &pos;
    f32 distance_limit, height_limit, distance, height;
    struct Hero *hero_state;

    *(OvlQuad *)p = *(OvlQuad *)from;
    for (i = 0; i < level_rail_count; i++) {
        if (skip != 0 && level_rails[i].owner == skip)
            continue;
        if (only != 0 && level_rails[i].owner != only)
            continue;
        if (*level_rails[i].owner == 0)
            continue;
        if (FastVecDist(&level_rails[i], p) > level_rails[i].sphere.f[3])
            continue;
        if (!find_nearest_path_point(level_rails[i].owner, p, to, &gotI, &gotF, level_rails[i].kind,
                              12.0f, 10.0f, 0.0f))
            continue;
        hero_state = &g_hero_r;
        distance_limit = 0.9f;
        height_limit = 1.5f;
        if ((u32)hero_state->state.control_mode < 2)
            distance_limit = 0.3f;
        if (hero_state->rail_catch_grace != 0) {
            height_limit = 10.0f;
            distance_limit += 0.5f;
        }
        distance = vec_distance_xy(p, to);
        height = FastAbsF(p->f[2] - to->f[2]);
        if (!(distance < distance_limit && height < height_limit))
            continue;
        *outOwner = level_rails[i].owner;
        *outI = gotI;
        *outF = gotF;
        *outKind = level_rails[i].kind;
        return 1;
    }
    return 0;
}
