/* Finds the listed object nearest a point. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/shared/ui_help_0020c758.c, FUN_L00_0020d8f8. */
char *find_best_hero_heading_target(float a, float b, float c, float d) {
    char *best = 0;
    float bd = 1.0e8f;
    int i = 0;
    char *o;
    while ((o = active_mobies[i]) != 0) {
        float *f = (float *)GetFlaggedPvarWord(o);
        if (f != 0 && *f != 0.0f && (*(unsigned short *)(o + 0x34) & 0x1000)) {
            int out;
            float dist = score_hero_target_candidate(o, b, a, c, d, &out);
            if (out == 0 && dist < bd) {
                bd = dist;
                best = o;
            }
        }
        i++;
    }
    return best;
}
/* Maps a small id to a text/sound id: 1 -> 0x79, 2 -> 0x77, 3 -> 0x75, otherwise 0. */
