        z->target_speed = 0.0f;
        if (z->gravity_mode) {
            z->motion.move_yaw = compute_hero_ground_aligned_heading();
        } else {
            z->motion.move_yaw = z->motion.rot.f[2];
        }
        q.q = 0;
